// Official circuit map coordinates; terrain is an interpretation of the
// documented undulations and Lukey Heights descent, not a survey.
export const islandPoint=(x,z)=>({x:(x-780)*.27,z:(z-490)*.27});
export const islandHeight=(x,z)=>.45+5.8*Math.exp(-(((x+114)/44)**2+((z+65)/36)**2))+1.8*Math.exp(-(((x-15)/110)**2+((z-32)/65)**2));
const route=[[640,660],[790,610],[930,562],[1005,536],[1050,528],[1105,540],[1145,566],[1180,609],[1215,660],[1255,703],[1295,724],[1340,722],[1375,702],[1390,670],[1382,634],[1355,598],[1295,548],[1235,499],[1175,451],[1120,418],[1070,401],[1020,399],[940,415],[870,431],[844,433],[828,425],[824,410],[836,390],[865,364],[910,341],[959,324],[984,304],[997,278],[992,253],[971,232],[945,223],[870,225],[810,230],[770,245],[690,281],[640,298],[603,300],[560,295],[500,277],[440,255],[400,247],[371,250],[345,265],[324,294],[313,330],[313,365],[322,416],[333,463],[328,484],[313,490],[290,482],[240,463],[213,460],[190,471],[173,494],[160,535],[158,585],[164,637],[180,694],[214,739],[252,759],[300,768],[360,758],[460,721],[550,690]];
