export const PHILLIP_ISLAND={id:'phillip-island',name:'Phillip Island',group:3,realWorld:true,revision:1,tag:'REAL WORLD · VICTORIA, AUSTRALIA',desc:'Lean through the coastal sweepers.<br>Crest Lukey Heights and brake for MG.',tags:['MOTORCYCLES · 12 TURNS','BASS STRAIT · ROLLING HILLS','4.445 KM LAYOUT'],type:'motorcycle',color:0x87a16b,road:0x3d4347,width:6.5,mapScale:3,mapSize:[450,300],bounds:[221,146],overviewHeight:320,overviewWidth:470,minimapSize:[240,160],elevationScale:null,walls:true,jumpAnchors:[],offroadDrag:3.4,barrierOffset:4.5,barrierOffsetAt:(u,side,p)=>{const tight=Math.max(Math.exp(-((p.x-12)**2+(p.z+22)**2)/500),Math.exp(-((p.x+122)**2+(p.z+2)**2)/500));return 1+(1-tight)*(side===1?2.8:5);},
 points:route.map(([x,z])=>{const p=islandPoint(x,z);return[p.x,islandHeight(p.x,p.z),p.z]})};
export function makeIslandTerrain(track){track.terrainHeight=islandHeight;const segments=track.nodes.filter((_,i)=>i%4===0);track.terrainDistance=(x,z)=>{let d=Infinity;for(let i=0;i<segments.length;i++){const a=segments[i],b=segments[(i+1)%segments.length],dx=b.x-a.x,dz=b.z-a.z,t=Math.max(0,Math.min(1,((x-a.x)*dx+(z-a.z)*dz)/(dx*dx+dz*dz)));d=Math.min(d,Math.hypot(x-a.x-t*dx,z-a.z-t*dz));}return d;};track.sections=anchors.map(([name,x,z])=>{const a=islandPoint(x,z);let index=0,d=Infinity;track.nodes.forEach((p,i)=>{const v=Math.hypot(p.x-a.x,p.z-a.z);if(v<d){d=v;index=i}});return{name,index,...a};}).sort((a,b)=>a.index-b.index);}
